const {test}=require('node:test');const assert=require('node:assert/strict');const ui=require('./practice.js');
test('private practice response must be explicitly non-public',()=>{assert.equal(ui.validate(null),null);for(const value of [undefined,[],{}, {practice_only:true,can_publish:true}])assert.throws(()=>ui.validate(value));const row={id:'fixture',version:1,state:'pending',history:[],practice_only:true,can_publish:false};assert.equal(ui.validate(row),row);for(const state of ['published','cleared','approved'])assert.throws(()=>ui.validate({...row,state}));});
test('untrusted practice text is escaped',()=>{assert.equal(ui.esc('<a "x">'), '&lt;a &quot;x&quot;&gt;');assert.equal(ui.esc(null),'');});
test('example is input text not a vote or approval record',()=>{assert.deepEqual(Object.keys(ui.example),['title','problem','desired_outcome']);assert.equal(Object.keys(ui.labels).length,4);assert.ok(ui.example.problem.length>=20);assert.equal(ui.labels.published,undefined);});
